  str_n5_mission_title_9 = "N6 — Primera línea predestinada",
  str_n5_mission_title_10 = "N7—Encomienda",
  str_n5_mission_title_11 = "N8—Contraataque",
  str_n5_mission_title_12 = "ST4—Cambiando el rumbo",
  str_n5_mission_title_13 = "N9—Línea defensiva",
  str_n5_mission_title_14 = "N10— Un enemigo formidable",
  str_n5_mission_title_15 = "N11 — De frente",
  str_n5_mission_title_16 = "ST5—Esperanza",
  str_n5_mission_desc_1 = "Mientras estás a bordo del Colossus, inesperadamente recibes un mensaje de un Subciudad Illumina.",
  str_n5_mission_desc_2 = "Llegas a Subciudad 24 y te encuentras con el oficial allí.",
  str_n5_mission_desc_3 = "Como miembros recién incorporados de su grupo de trabajo, el oficial Brent parece estar muy preocupado por tu desempeño.",
  str_n5_mission_desc_4 = "Te unes al convoy sin problemas, pero antes de comenzar tu misión, Brent te informa que la camaradería es vital para promover la cooperación dentro de cualquier equipo.",
  str_n5_mission_desc_5 = "Entre la tormenta de polvo y los Eclipsites, el convoy parece incapaz de continuar su misión de transporte, pero Ansia se niega a rendirse tan fácilmente.",
  str_n5_mission_desc_6 = "El ejército Eclipsite se acerca, pero no hay fuerzas presentes capaces de defender Subciudad 24 ...",
  str_n5_mission_desc_7 = "Mientras el gigante Eclipsite volador ataca, ¡derribarlo parece ser el mejor plan de acción!",
  str_n5_mission_desc_8 = "Cuando se enfrentan a los Eclipsites más poderosos, siempre hay quienes se levantan con una valentía inigualable.",
  str_n5_mission_desc_9 = "En el cruel campo de batalla, solo hay una delgada línea entre la victoria y la derrota.",
  str_n5_mission_desc_10 = "Habiendo heredado la voluntad de resistencia, ahora debes enfrentarte a tu enemigo más amenazante una vez más...",
  str_n5_mission_desc_11 = "El contraataque aún no ha terminado. ¡Ahora debes llevar la noticia de tu victoria a tu camarada de armas!",
  str_n5_mission_desc_12 = "La defensa de la Subciudad 24 es solo una parte de esta batalla. Ahora fijas tu mirada en otro objetivo.",
  str_n5_mission_desc_13 = "Subciudad 23 posicionado en la línea defensiva se enfrenta a continuos ataques del ejército Eclipsite. ¿Cómo cambiará la situación tu llegada?",
  str_n5_mission_desc_14 = "Después de que Barton aparece con sus tropas, recuperas con éxito la retaguardia, pero ¿puede todo ir tan bien como parece?",
  str_n5_mission_desc_15 = "Al enfrentarse a un enemigo poderoso una vez más, ni uno solo de ustedes está listo para retroceder. Esta batalla no solo servirá como un paso hacia la victoria final, ¡debe ganarse en honor a los héroes caídos que vinieron antes que tú!",
  str_n5_mission_desc_16 = "De regreso a Subciudad 24, todos deciden por qué tipo de futuro desean luchar.",
  str_n5_mission_desc_long_1 = "Tienes un problema técnico al intentar ponerte en contacto con Illumina. Después de ajustar el dispositivo de comunicación, inesperadamente recibes un mensaje de Subciudad 24 solicitando asistencia. Convencido por el razonamiento de Vice, finalmente decides ir a Subciudad 24.",
  str_n5_mission_desc_long_2 = "Aterrizas en la estación de transporte y es allí donde te encuentras con el Oficial Brent. Después de escuchar tus intenciones, el oficial, que dirige el grupo de trabajo Subciudad 24, decide incorporarte a sus fuerzas en el acto.",
  str_n5_mission_desc_long_3 = "Inseguro de tu condición física y habilidades de mando, el Oficial Brent exige que le demuestres de inmediato exactamente cómo combates a los Eclipsites. Justo cuando estás en peligro de ser abrumado por los Eclipsites, aparece un soldado llamado Gram.",
  str_n5_mission_desc_long_4 = "Ansia, que está con el convoy, le pide ayuda, con la esperanza de que pueda ayudar a los otros dos miembros del convoy en disputa a reconciliar sus diferencias. Después de escuchar sus historias, descubres que la causa de todo esto es la propia Ansia.",
  str_n5_mission_desc_long_5 = "Ansia, el líder del convoy, te pide seriamente que uses el Colossus para transportar las mercancías a Subciudad 23. Durante el poco tiempo que tienes para prepararte, descubres que el talento secreto de Gram está en la cocina.",
  str_n5_mission_desc_long_6 = "Frente al ejército Eclipsite, Brent mantiene la calma ante el peligro. Ordena que se utilice el Colossus para evacuar a algunos de los civiles y divide las fuerzas disponibles de la ciudad en dos unidades. Una unidad está encargada de lanzar un ataque contra el jefe Eclipsite, mientras que las fuerzas restantes reciben el comando de ayudar en el esfuerzo de bombardeo para hacer frente a los Eclipsites que atacan la ciudad.",
  str_n5_mission_desc_long_7 = "El oficial veterano de Subciudad 24 derriba con éxito al jefe de Eclipsite. Te diriges a donde cae, de acuerdo con el plan actual, y te preparas para terminarlo. Sin embargo, lo impredecible es la única constante en el campo de batalla, y una explosión que hace temblar la tierra llena el aire.",
  str_n5_mission_desc_long_8 = "Mientras el gigante Eclipsite ataca Subciudad 24, Brent rápidamente formula un plan de batalla y decide tomar un pequeño escuadrón para enfrentarlo. En última instancia, usan el terreno y las trampas de minas en la estación para suprimir con éxito el poderoso Eclipsite.",
  str_n5_mission_desc_long_9 = "Después de haber escapado con suerte de la explosión, regresas con ansias a la estación. Sin embargo, el jefe Eclipsite caído, que se cree que fue destruido por la explosión, surge una vez más y ataca a Brent...",
  str_n5_mission_desc_long_10 = "Brent recibe un golpe directo del enemigo Eclipsite, pero su espíritu se mantiene fuerte contra el miedo a la muerte. Al ver tu rápida llegada, él cree que puedes derrotar al Eclipsite y defender Subciudad.",
  str_n5_mission_desc_long_11 = "A través de su perseverancia inquebrantable, la defensa de Subciudad 24 finalmente está asegurada. Gram decide llevar la noticia de tu victoria a su hermano de armas de aquellos años pasados y despedirse de él.",
  str_n5_mission_desc_long_12 = "Después de deducir que el objetivo de los Eclipsites es, de hecho, la carga que transporta el convoy, decides escoltar estos importantes suministros hasta su destino final—Subciudad 23 en la Línea Dunefire, hasta la vanguardia contra el ataque de los Eclipsites.",
  str_n5_mission_desc_long_13 = "Después de usar el Colossus y tu habilidad psíquica para determinar la situación a lo largo de la línea defensiva, Gram, que posee años de experiencia en combate, decide lanzar una incursión en los Eclipsites para poner fin al asedio de Subciudad 23. Y así, decides firmemente... ¡saltar directamente del Colossus y aterrizar detrás de la línea enemiga!",
  str_n5_mission_desc_long_14 = "Aunque la marea parecía haber cambiado, las nubes oscuras se acumulan en lo alto una vez más cuando el jefe Eclipsite aparece una vez más.",
  str_n5_mission_desc_long_15 = "Frente a este formidable enemigo una vez más, todos están completamente preparados para la batalla. Impulsado por la ira y la determinación, aniquilas a tu enemigo, marcando tu victoria en la defensa de Subciudad 23 y tu éxito final en la protección de la línea defensiva.",
  str_n5_mission_desc_long_16 = "Después de que la Vanguardia Dunefire declaró su victoria defensiva completa, regresas a Subciudad24. En medio de la quietud de la euforia posterior a la batalla, todos deciden los respectivos caminos que desean tomar en el futuro— vivir por sus ideales y luchar codo con codo, con y para sus compatriotas.",
  str_n5_battlefield_refreshed = "Reinicio del campo de batalla",
  str_n5_record_militaryexploit = "Se registrará el mérito obtenido.",
  str_n5_today_max_militaryexploit = "De los cuatro campos de batalla siguientes, solo el campo de batalla en el que obtuviste tu mérito más alto durante el día se agregará a tu mérito total."
}
return config
